```cpp
#include <iostream>
#include <string>
#include <regex>
#include <unordered_map>

// Define a map to convert Markdown to HTML
const std::unordered_map<std::string, std::string> markdown_to_html{
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"`", "<code>"},
    {"**", "<strong>"},
    {"__", "<strong>"},
    {"*", "<em>"},
    {"_", "<em>"},
    {"[", "<a href=\""],
    {"](", "\"></a>"),
    {"|", "<table><tr>"},
    {"|", "</td><td>"},
    {"|", "</td></tr></table>"},
    {"---", "<hr>"},
    {"\\n", "<br>"}
};

std::string convert_markdown_to_html(std::string& markdown) {
    std::string html;

    // Replace line breaks with <br>
    markdown = std::regex_replace(markdown, std::regex("\\n"), "\\n");

    // Convert Markdown to HTML
    std::string current_tag;
    for (char c : markdown) {
        if (c == '\\') {  // Escape character
            html += c;
            continue;
        }
        auto it = markdown_to_html.find(std::string(1, c));
        if (it != markdown_to_html.end()) {
            if (!current_tag.empty()) {
                html += current_tag + ">";
                current_tag.clear();
            }
            html += it->second;
        } else {
            if (c == '[') {
                int open_brackets = 1, link_start = markdown.find(c);
                while (markdown[link_start + open_brackets] == '[') {
                    open_brackets++;
                }
                int link_end = markdown.find(']', link_start + 1);
                if (link_end != std::string::npos && open_brackets > 1) {
                    std::string link = markdown.substr(link_start + 1, link_end - link_start - 1);
                    html += "<a href=\"" + link + "\">";
                    current_tag = "</a>";
                }
            } else if (c == '|') {
                if (!current_tag.empty()) {
                    html += current_tag + ">";
                    current_tag.clear();
                }
                if (html.back() != '<') {
                    html += "<table><tr>";
                } else {
                    html += "</td><td>";
                }
            } else if (c == '-') && (markdown[markdown.find(c) + 1] == '-' && markdown[markdown.find(c) + 2] == '-')) {
                html += "<hr>";
            } else {
                html += c;
            }
        }
    }
    if (!current_tag.empty()) {
        html += current_tag + ">";
        current_tag.clear();
    }

    return html;
}

int main() {
    std::string markdown = "Hello **world**!\n\nThis is a [link](https://example.com/) in Markdown.";
    std::string html = convert_markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This implementation uses a map `markdown_to_html` to convert Markdown syntax to HTML tags. It also handles basic Markdown constructs like headers, inline formatting, links, tables, horizontal rules, and line breaks.

To use this function, simply pass a reference to a std::string containing Markdown text:

```cpp
std::string markdown = "Hello **world**!\n\nThis is a [link](https://example.com/) in Markdown.";
std::string html = convert_markdown_to_html(markdown);
```

Note that this implementation is not a complete Markdown parser and may not handle all possible Markdown variations. It's recommended to use a more robust Markdown library if you need to handle complex Markdown documents.

